/// Настройки сборки.
///
/// Всё `const` и с рабочим значением по умолчанию, чтобы обычный
/// `flutter run` запускался. Ответ на вопрос «куда смотрит эта сборка» —
/// чтение одного файла, а не grep по литералам.
abstract final class Env {
  /// Собирать контейнер из моков вместо локальной базы.
  ///
  /// По умолчанию выключено: справочник и заявки обязаны переживать
  /// перезапуск, а данные в памяти этого не умеют. Моки остаются вторым
  /// входом — для скриншотов и ручной проверки сценария на заведомо
  /// известных данных: `flutter run --dart-define=MOCKS=true`.
  ///
  /// Флаг `const`, поэтому неиспользованная ветка выбрасывается компилятором.
  static const bool useMocks = bool.fromEnvironment('MOCKS');
}
